	private enum Profile {
		CURRENT(true, true, false),
		AUTO_REBUILD_OFF(true, false, false),
		DISABLED(false, true, false),
		EXCLUDED(true, true, true);

		private final boolean enabled;
		private final boolean autoRebuild;
		private final boolean excluded;

		Profile(boolean enabled, boolean autoRebuild, boolean excluded) {
			this.enabled = enabled;
			this.autoRebuild = autoRebuild;
			this.excluded = excluded;
		}

		boolean tracked() {
			return enabled && !excluded;
		}

		LmdbStoreConfig config(boolean inline) {
			return config(inline, false);
		}

		LmdbStoreConfig config(boolean inline, boolean experimental) {
			LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setTripleTermIndexes("spoc,cspo,posc")
					.setInlineLiterals(inline)
					.setForceSync(true)
					.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
					.setPredicateGuaranteeIndexEnabled(enabled)
					.setPredicateGuaranteeIndexAutoRebuild(autoRebuild);
			config.setExperimentalQueryOptimizations(experimental);
			if (excluded) {
				config.setPredicateGuaranteeExcludedPredicates(PREDICATE.stringValue());
			}
			return config;
		}
	}

