	@ParameterizedTest(name = "{0}, {1}, inline={2}, {3}")
	@MethodSource("completionCases")
	void bulkDomainsCoverLoadedRowsThroughAppendDeleteAndColdReopen(Seed seed, Later later, boolean inline,
			Profile profile) throws Exception {
		Path target = directory.resolve("store");
		Value loaded = seed.value();
		Value appended = later.value();
		List<Statement> initial = initialRows(loaded);
		Set<Statement> expectedRows = new LinkedHashSet<>(initial);
		load(target, profile.config(inline), initial);
		RdfTermDomain loadedDomain = RdfTermDomain.classify(loaded);
		RdfTermDomain mixedDomain = loadedDomain.combine(RdfTermDomain.classify(appended));
		Map<Value, Long> originalIds;
		try (Opened opened = open(target, profile.config(inline), false)) {
			assertQueryBags(opened, expectedRows);
			assertDomain(opened, profile, loadedDomain);
			originalIds = ids(opened, List.of(LOADED_SUBJECT, PREDICATE, loaded, FIRST_GRAPH, SECOND_GRAPH));
			Statement addition = VF.createStatement(APPENDED_SUBJECT, PREDICATE, appended, FIRST_GRAPH);
			try (var connection = opened.repository().getConnection()) {
				connection.begin();
				connection.add(addition);
				connection.add(addition);
				connection.commit();
			}
			expectedRows.add(addition);
			assertQueryBags(opened, expectedRows);
			assertDomain(opened, profile, mixedDomain);
		}

		// Candidate-only degradation rows must retain prepared admission and the exact owned triple generation.
		try (Opened opened = open(target, profile.config(inline, true), false)) {
			assertQueryBags(opened, expectedRows);
			assertDomain(opened, profile, mixedDomain);
			assertIds(opened, originalIds);
			try (var connection = opened.repository().getConnection()) {
				connection.remove(LOADED_SUBJECT, PREDICATE, loaded, FIRST_GRAPH);
			}
			expectedRows.remove(initial.get(0));
			assertQueryBags(opened, expectedRows);
			assertDomain(opened, profile, mixedDomain);
		}

		boolean requiredMaintenance = profile.tracked() && profile.autoRebuild;
		try (Opened opened = open(target, profile.config(inline), requiredMaintenance)) {
			// The remaining named-context copy still constrains every predicate-wide guarantee.
			assertQueryBags(opened, expectedRows);
			assertDomain(opened, profile, mixedDomain);
			assertIds(opened, originalIds);
			try (var connection = opened.repository().getConnection()) {
				connection.begin();
				// Keep the actual old owners live so dictionary reclamation cannot masquerade as domain work.
				connection.add(LOADED_SUBJECT, RETAINED_OWNER, loaded, SECOND_GRAPH);
				connection.remove(LOADED_SUBJECT, PREDICATE, loaded, SECOND_GRAPH);
				connection.commit();
			}
			expectedRows.remove(initial.get(1));
			assertQueryBags(opened, expectedRows);
			assertDomain(opened, profile, mixedDomain);
		}

		RdfTermDomain remainingDomain = RdfTermDomain.classify(appended);
		try (Opened opened = open(target, profile.config(inline, true), requiredMaintenance)) {
			assertQueryBags(opened, expectedRows);
			assertDomain(opened, profile, profile.autoRebuild ? remainingDomain : mixedDomain);
			assertIds(opened, originalIds);
		}
		if (profile != Profile.CURRENT) {
			// A deferred request, disabled schema, or exclusion transition must still be honored when enabled.
			try (Opened opened = open(target, Profile.CURRENT.config(inline, true), true)) {
				assertQueryBags(opened, expectedRows);
				assertDomain(opened, Profile.CURRENT, remainingDomain);
				assertIds(opened, originalIds);
			}
		}
	}

